#include "soc.h"
static void cs(int high){REG32(SPI_BASE+4)=high?1:0;}
static uint8_t xfer(uint8_t v){REG32(SPI_BASE+12)=v;while(REG32(SPI_BASE+8)&1);return REG32(SPI_BASE+12);}
static void addr3(uint32_t a){xfer(a>>16);xfer(a>>8);xfer(a);}
static void cmd(uint8_t c){cs(0);xfer(c);cs(1);}
static void wren(void){cmd(0x06);}
static uint8_t status(void){uint8_t s;cs(0);xfer(0x05);s=xfer(0xff);cs(1);return s;}
static int wait_ready(void){uint32_t t=read_mtime_ticks32();while(status()&1)if((uint32_t)(read_mtime_ticks32()-t)>TIMEBASE_HZ*10u)return -1;return 0;}
uint32_t flash_read_jedec_id(void){uint32_t id;cs(0);xfer(0x9f);id=(uint32_t)xfer(0xff)<<16;id|=(uint32_t)xfer(0xff)<<8;id|=xfer(0xff);cs(1);return id;}
int flash_read(uint32_t a,void*dst,uint32_t n){uint8_t*p=dst;uint32_t i;if(a>=FLASH_LIMIT_ADDR||n>FLASH_LIMIT_ADDR-a)return -1;cs(0);xfer(0x03);addr3(a);for(i=0;i<n;i++)p[i]=xfer(0xff);cs(1);return 0;}
static int erase4k(uint32_t a){wren();cs(0);xfer(0x20);addr3(a);cs(1);return wait_ready();}
static int page_program(uint32_t a,const uint8_t*p,uint32_t n){uint32_t i;wren();cs(0);xfer(0x02);addr3(a);for(i=0;i<n;i++)xfer(p[i]);cs(1);return wait_ready();}
static int program(uint32_t a,const void*src,uint32_t n){const uint8_t*p=src;uint32_t k;while(n){k=256-(a&255);if(k>n)k=n;if(page_program(a,p,k))return -1;a+=k;p+=k;n-=k;}return 0;}
static int flash_crc32(uint32_t a,uint32_t n,uint32_t*out){uint8_t buf[256];uint32_t off,k,crc=0xffffffffu;for(off=0;off<n;off+=k){k=n-off;if(k>sizeof(buf))k=sizeof(buf);if(flash_read(a+off,buf,k))return -1;crc=crc32_update(crc,buf,k);}*out=crc^0xffffffffu;return 0;}
static int header_equal(const image_header_t*a,const image_header_t*b){return a->magic==b->magic&&a->version==b->version&&a->load_addr==b->load_addr&&a->entry_addr==b->entry_addr&&a->length==b->length&&a->crc32==b->crc32&&a->flags==b->flags&&a->header_crc32==b->header_crc32;}
int flash_write_image(uint32_t ram,uint32_t len,uint32_t load,uint32_t entry,uint32_t flags){image_header_t h,v;uint32_t a,end,crc,verify_crc,id;if(!len||!ddr_range_valid(ram,len)||!ddr_range_valid(load,len)||!ddr_entry_valid(entry)||len>FLASH_LIMIT_ADDR-FLASH_PAYLOAD_ADDR)return -1;id=flash_read_jedec_id();if((id&0xffu)!=0x18u){console_puts("Refusing Flash erase: unsupported JEDEC ID=");console_hex(id);console_putc('\n');return -5;}console_puts("Flash JEDEC ID=");console_hex(id);console_puts("; erasing user partition...\n");end=(FLASH_PAYLOAD_ADDR+len+4095)&~4095u;for(a=FLASH_HEADER_ADDR;a<end;a+=4096){if(erase4k(a))return -2;console_putc('.');}console_putc('\n');console_puts("Programming payload...\n");if(program(FLASH_PAYLOAD_ADDR,(const void*)(uintptr_t)ram,len))return -3;crc=crc32_update(0xffffffffu,(const void*)(uintptr_t)ram,len)^0xffffffffu;console_puts("Verifying Flash payload...\n");if(flash_crc32(FLASH_PAYLOAD_ADDR,len,&verify_crc)||verify_crc!=crc){console_puts("Flash payload CRC mismatch\n");return -6;}h.magic=IMAGE_MAGIC;h.version=1;h.load_addr=load;h.entry_addr=entry;h.length=len;h.crc32=crc;h.flags=flags;h.header_crc32=crc32_update(0xffffffffu,&h,28)^0xffffffffu;if(program(FLASH_HEADER_ADDR,&h,sizeof(h)))return -4;if(flash_read(FLASH_HEADER_ADDR,&v,sizeof(v))||!header_equal(&h,&v)){console_puts("Flash header verify failed\n");return -7;}console_puts("Flash image committed, CRC=");console_hex(crc);console_putc('\n');return 0;}
int flash_read_header(image_header_t*h){if(flash_read(FLASH_HEADER_ADDR,h,sizeof(*h)))return -1;if(h->magic!=IMAGE_MAGIC||h->version!=1||!ddr_range_valid(h->load_addr,h->length)||!ddr_entry_valid(h->entry_addr)||h->length>FLASH_LIMIT_ADDR-FLASH_PAYLOAD_ADDR)return -2;if((crc32_update(0xffffffffu,h,28)^0xffffffffu)!=h->header_crc32)return -3;return 0;}
int flash_load_image(image_header_t*out){image_header_t h;uint8_t*p;uint32_t off,n,crc;int r=flash_read_header(&h);if(r)return r;console_puts("Loading Flash image to ");console_hex(h.load_addr);console_puts(", bytes=");console_dec(h.length);console_putc('\n');p=(uint8_t*)(uintptr_t)h.load_addr;crc=0xffffffffu;for(off=0;off<h.length;off+=n){n=h.length-off;if(n>1024)n=1024;flash_read(FLASH_PAYLOAD_ADDR+off,p+off,n);crc=crc32_update(crc,p+off,n);}crc^=0xffffffffu;if(crc!=h.crc32)return -4;*out=h;return 0;}
